import type { Metadata } from 'next';

export const metadata: Metadata = {
  title: 'Theme Settings',
  description: 'Display user theme and language preferences'
};

export default function RootLayout({
  children
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}

input.content:
import { cookies, headers } from 'next/headers';

export default function ThemePreference() {
  const cookieStore = cookies();
  const theme = cookieStore.get('theme')?.value || 'light';

  const headersList = headers();
  const acceptLanguage = headersList.get('accept-language') || 'en-US,en';

  const preferredLanguage = acceptLanguage.split(',')[0] || 'en-US';

  return (
    <div className="theme-preference">
      <h1>User Preferences</h1>
      <div className="preference-item">
        <span className="label">Theme:</span>
        <span className={`value theme-${theme}`}>{theme}</span>
      </div>
      <div className="preference-item">
        <span className="label">Preferred Language:</span>
        <span className="value">{preferredLanguage}</span>
      </div>
    </div>
  );
}

